using LibraryManagement.Application.DTOs;using LibraryManagement.Application.Services.Base;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;
namespace LibraryManagement.Controllers;[Authorize]public class BooksController(IBookService service):Controller{public async Task<IActionResult> Index()=>View(await service.GetAllAsync());public async Task<IActionResult> Details(string uuid){var x=await service.GetDetailsAsync(uuid);return x is null?NotFound():View(x);}[HttpGet]public async Task<IActionResult>Create(){await Lists();return View(new BookCreateDto());}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(BookCreateDto dto){if(ModelState.IsValid){await service.AddAsync(dto);return RedirectToAction(nameof(Index));}await Lists();return View(dto);}[HttpGet]public async Task<IActionResult>Edit(string uuid){var x=await service.GetForUpdateAsync(uuid);if(x is null)return NotFound();await Lists();return View(x);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(BookUpdateDto dto){if(ModelState.IsValid){await service.UpdateAsync(dto);return RedirectToAction(nameof(Index));}await Lists();return View(dto);}[HttpGet]public async Task<IActionResult>Delete(string uuid){var x=await service.GetDetailsAsync(uuid);return x is null?NotFound():View(x);}[HttpPost,ActionName("Delete"),ValidateAntiForgeryToken]public async Task<IActionResult>DeleteConfirmed(string uuid){var x=await service.GetDetailsAsync(uuid);if(x is null)return NotFound();try{await service.DeleteAsync(uuid);return RedirectToAction(nameof(Index));}catch(InvalidOperationException e){ModelState.AddModelError("",e.Message);return View("Delete",x);}}async Task Lists()=>ViewBag.Categories=new SelectList(await service.GetCategoriesAsync(),"Id","Name");}
